package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonAnyGetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class ThrowableDeserializerTest {

    static class Problem extends Exception {
        @JsonAnySetter
        @JsonAnyGetter
        public Map<String, Object> additionalProperties = new HashMap<>();

        // Default constructor for deserialization
        public Problem() {
            super();
        }

        // Constructor with message
        public Problem(String message) {
            super(message);
        }
    }

    @Test
    public void testDeserializeThrowableWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance and set an additional property
        Problem original = new Problem("test message");
        original.additionalProperties.put("additional", "additional value");

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize - should not throw NPE
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify the message
        assertEquals("test message", deserialized.getMessage());
        // Verify the additional property
        assertNotNull(deserialized.additionalProperties);
        assertEquals("additional value", deserialized.additionalProperties.get("additional"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterWithoutMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance without a message, but with an additional property
        Problem original = new Problem();
        original.additionalProperties.put("extra", "extra value");

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize - should not throw NPE
        Problem deserialized = mapper.readValue(json, Problem.class);

        // Verify the message is null (or empty)
        assertNull(deserialized.getMessage());
        // Verify the additional property
        assertNotNull(deserialized.additionalProperties);
        assertEquals("extra value", deserialized.additionalProperties.get("extra"));
    }

    @Test
    public void testDeserializeThrowableWithAnySetterAndMultipleProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Create an instance with multiple additional properties
        Problem original = new Problem("another message");
        original.additionalProperties.put("key1", "value1");
        original.additionalProperties.put("key2", 42);
        original.additionalProperties.put("key3", true);

        // Serialize
        String json = mapper.writeValueAsString(original);
        // Deserialize
        Problem deserialized = mapper.readValue(json, Problem.class);

        assertEquals("another message", deserialized.getMessage());
        assertEquals("value1", deserialized.additionalProperties.get("key1"));
        assertEquals(42, deserialized.additionalProperties.get("key2"));
        assertEquals(true, deserialized.additionalProperties.get("key3"));
    }
}

