package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.type.ArrayType;
import org.junit.Test;

import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertEquals;

public class TestPrimitiveArrayDeserializerModifier {
    static class TestBean {
        public byte[] primitiveArray;
        public Byte[] wrapperArray;
    }

    static class CountingModifier extends BeanDeserializerModifier {
        final AtomicInteger primitiveArrayCount = new AtomicInteger();
        final AtomicInteger wrapperArrayCount = new AtomicInteger();

        @Override
        public JsonDeserializer<?> modifyArrayDeserializer(DeserializationConfig config,
                ArrayType valueType, BeanDescription beanDesc, JsonDeserializer<?> deserializer) {
            Class<?> raw = valueType.getRawClass();
            if (raw == byte[].class) {
                primitiveArrayCount.incrementAndGet();
            } else if (raw == Byte[].class) {
                wrapperArrayCount.incrementAndGet();
            }
            return deserializer;
        }
    }

    @Test
    public void testPrimitiveArrayDeserializerCapturedByModifier() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        CountingModifier modifier = new CountingModifier();
        SimpleModule module = new SimpleModule();
        module.setDeserializerModifier(modifier);
        mapper.registerModule(module);

        TestBean bean = new TestBean();
        bean.primitiveArray = new byte[] { 0x11, 0x22 };
        bean.wrapperArray = new Byte[] { 0x33, 0x44 };

        String json = mapper.writeValueAsString(bean);
        TestBean result = mapper.readValue(json, TestBean.class);

        // Verify deserialization worked
        assertEquals(2, result.primitiveArray.length);
        assertEquals(0x11, result.primitiveArray[0]);
        assertEquals(0x22, result.primitiveArray[1]);
        assertEquals(2, result.wrapperArray.length);
        assertEquals(Byte.valueOf((byte)0x33), result.wrapperArray[0]);
        assertEquals(Byte.valueOf((byte)0x44), result.wrapperArray[1]);

        // Verify modifier was called for both arrays
        assertEquals(1, modifier.primitiveArrayCount.get());
        assertEquals(1, modifier.wrapperArrayCount.get());
    }
}

