package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;
import static org.junit.Assert.*;

public class BeanUtilTest {

    private final TypeFactory typeFactory = TypeFactory.defaultInstance();

    @Test
    public void testIsJava8OptionalClass() {
        // Test with various optional classes
        assertTrue(BeanUtil.isJava8OptionalClass(java.util.Optional.class));
        assertTrue(BeanUtil.isJava8OptionalClass(java.util.OptionalInt.class));
        assertTrue(BeanUtil.isJava8OptionalClass(java.util.OptionalLong.class));
        assertTrue(BeanUtil.isJava8OptionalClass(java.util.OptionalDouble.class));
        // Negative cases
        assertFalse(BeanUtil.isJava8OptionalClass(String.class));
        assertFalse(BeanUtil.isJava8OptionalClass(java.util.ArrayList.class));
    }

    @Test
    public void testCheckUnsupportedTypeForJava8Optional() {
        // Test with Optional
        JavaType optionalType = typeFactory.constructType(java.util.Optional.class);
        String result = BeanUtil.checkUnsupportedType(optionalType);
        assertNotNull(result);
        assertTrue(result.contains("Java 8 optional"));
        assertTrue(result.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));

        // Test with OptionalInt
        JavaType optionalIntType = typeFactory.constructType(java.util.OptionalInt.class);
        result = BeanUtil.checkUnsupportedType(optionalIntType);
        assertNotNull(result);
        assertTrue(result.contains("Java 8 optional"));
        assertTrue(result.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));

        // Test with OptionalLong
        JavaType optionalLongType = typeFactory.constructType(java.util.OptionalLong.class);
        result = BeanUtil.checkUnsupportedType(optionalLongType);
        assertNotNull(result);
        assertTrue(result.contains("Java 8 optional"));
        assertTrue(result.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));

        // Test with OptionalDouble
        JavaType optionalDoubleType = typeFactory.constructType(java.util.OptionalDouble.class);
        result = BeanUtil.checkUnsupportedType(optionalDoubleType);
        assertNotNull(result);
        assertTrue(result.contains("Java 8 optional"));
        assertTrue(result.contains("com.fasterxml.jackson.datatype:jackson-datatype-jdk8"));

        // Test with a supported type (should return null)
        JavaType stringType = typeFactory.constructType(String.class);
        result = BeanUtil.checkUnsupportedType(stringType);
        assertNull(result);
    }
}

