package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonRootName;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.Test;

import static org.junit.Assert.*;

public class ObjectMapperValueToTreeWrapRootValueTest {

    @JsonRootName("event")
    public static class Event {
        public Long id;
        public String name;

        public Event() {}

        public Event(Long id, String name) {
            this.id = id;
            this.name = name;
        }
    }

    @Test
    public void testValueToTreeWithWrapRootValue() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event(123L, "testEvent");
        JsonNode node = mapper.valueToTree(event);

        // The root node should be an object with a single field named "event"
        assertTrue(node.isObject());
        assertEquals(1, node.size());
        assertTrue(node.has("event"));

        // The "event" field should be an object with the properties of Event
        JsonNode eventNode = node.get("event");
        assertTrue(eventNode.isObject());
        assertEquals(123L, eventNode.get("id").asLong());
        assertEquals("testEvent", eventNode.get("name").asText());
    }

    @Test
    public void testValueToTreeWithoutWrapRootValue() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event(123L, "testEvent");
        JsonNode node = mapper.valueToTree(event);

        // Without WRAP_ROOT_VALUE, the node should be a direct representation of Event
        assertTrue(node.isObject());
        assertEquals(2, node.size());
        assertTrue(node.has("id"));
        assertTrue(node.has("name"));
        assertEquals(123L, node.get("id").asLong());
        assertEquals("testEvent", node.get("name").asText());
    }
}

