package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.Locale;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class LocaleDeserializationTest {
    @Test
    public void testEmptyStringToLocaleWithAcceptEmptyStringAsNullObject() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);

        // Before the fix, this would return null. After the fix, it should return Locale.ROOT.
        Locale result = mapper.readValue("\"\"", Locale.class);
        assertNotNull("Deserialized Locale should not be null", result);
        assertEquals(Locale.ROOT, result);
    }

    @Test
    public void testEmptyStringToLocaleWithoutFeature() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT);

        // Without the feature, empty string should still convert to Locale.ROOT.
        Locale result = mapper.readValue("\"\"", Locale.class);
        assertNotNull("Deserialized Locale should not be null", result);
        assertEquals(Locale.ROOT, result);
    }
}

