package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectReader;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import java.io.IOException;
import java.util.Date;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Unit tests for verifying that deep nested arrays are rejected when
 * {@link DeserializationFeature#UNWRAP_SINGLE_VALUE_ARRAYS} is enabled.
 * This covers the fix for CVE-2022-42003.
 */
public class StdDeserializerNestedArrayTest {

    private final ObjectMapper MAPPER = new ObjectMapper()
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

    // Helper method to assert that parsing nested array throws an exception
    private void assertNestedArrayThrows(String json, Class<?> valueType) throws IOException {
        try {
            MAPPER.readValue(json, valueType);
            fail("Expected JsonMappingException for nested array with " + valueType.getSimpleName());
        } catch (JsonMappingException e) {
            // Expected
            // Also ensure the message contains the expected text
            String message = e.getMessage();
            assertTrue("Exception message should mention nested arrays: " + message,
                    message.contains("nested Arrays not allowed"));
        }
    }

    @Test
    public void testBooleanPrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[true]]", boolean.class);
    }

    @Test
    public void testBytePrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1]]", byte.class);
    }

    @Test
    public void testShortPrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1]]", short.class);
    }

    @Test
    public void testIntPrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1]]", int.class);
    }

    @Test
    public void testLongPrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1]]", long.class);
    }

    @Test
    public void testFloatPrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1.0]]", float.class);
    }

    @Test
    public void testDoublePrimitiveNestedArray() throws IOException {
        assertNestedArrayThrows("[[1.0]]", double.class);
    }

    @Test
    public void testDateNestedArray() throws IOException {
        // Date deserialization: default format is timestamp or ISO-8601
        // We'll use a simple number (timestamp) wrapped in nested array.
        assertNestedArrayThrows("[[1000000]]", Date.class);
    }

    // Also test for wrapper types? The patch primarily affects primitives and Date,
    // but _deserializeWrappedValue is also changed. Let's test a wrapper type.
    @Test
    public void testBooleanWrapperNestedArray() throws IOException {
        // Boolean wrapper uses the same deserializer? Actually Boolean deserializer
        // extends from StdDeserializer and uses _parseBooleanPrimitive? 
        // We'll test Boolean.class to be safe.
        assertNestedArrayThrows("[[true]]", Boolean.class);
    }

    @Test
    public void testIntegerWrapperNestedArray() throws IOException {
        assertNestedArrayThrows("[[1]]", Integer.class);
    }

    // Test that a single array (not nested) still works correctly.
    @Test
    public void testSingleArrayUnwrappingBoolean() throws IOException {
        boolean value = MAPPER.readValue("[true]", boolean.class);
        assertTrue(value);
    }

    @Test
    public void testSingleArrayUnwrappingInt() throws IOException {
        int value = MAPPER.readValue("[42]", int.class);
        assertTrue(value == 42);
    }

    @Test
    public void testSingleArrayUnwrappingDate() throws IOException {
        Date date = MAPPER.readValue("[1000000]", Date.class);
        assertTrue(date.getTime() == 1000000L);
    }

    // Additional test for _deserializeWrappedValue: we can test with a custom
    // deserializer that uses it. But we can also test via a type that uses
    // StdDeserializer's default handling. For simplicity, we can test with
    // a simple POJO that has a field of primitive type and uses default deserialization.
    // However, the change in _deserializeWrappedValue is covered by the above tests
    // because they trigger the same code path? Actually, the above tests directly
    // call the primitive deserializers. The _deserializeWrappedValue is used by
    // other deserializers. Let's create a test for a POJO with a primitive field.
    static class SimpleBean {
        public int value;
    }

    @Test
    public void testPojoWithPrimitiveFieldNestedArray() throws IOException {
        // This should throw because the field is a primitive int and we have nested array.
        try {
            MAPPER.readValue("{\"value\":[[1]]}", SimpleBean.class);
            fail("Expected JsonMappingException for nested array in POJO field");
        } catch (JsonMappingException e) {
            // Expected
            String message = e.getMessage();
            assertTrue("Exception message should mention nested arrays: " + message,
                    message.contains("nested Arrays not allowed"));
        }
    }

    // Test that the exception is thrown even if the nesting is deeper than 2 levels.
    @Test
    public void testDeepNestedArray() throws IOException {
        // Three levels of nesting.
        assertNestedArrayThrows("[[[true]]]", boolean.class);
    }
}

