import java.util.Date;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class StdDeserializerNestedArrayTest {

    private final ObjectMapper mapper = new ObjectMapper()
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

    // Helper method to create a nested array JSON string
    private String nestedArray(int depth) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < depth; i++) {
            sb.append('[');
        }
        sb.append("true");
        for (int i = 0; i < depth; i++) {
            sb.append(']');
        }
        return sb.toString();
    }

    // Helper for numeric values
    private String nestedArray(int depth, String value) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < depth; i++) {
            sb.append('[');
        }
        sb.append(value);
        for (int i = 0; i < depth; i++) {
            sb.append(']');
        }
        return sb.toString();
    }

    // Helper for date
    private String nestedArrayDate(int depth, long timestamp) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < depth; i++) {
            sb.append('[');
        }
        sb.append(timestamp);
        for (int i = 0; i < depth; i++) {
            sb.append(']');
        }
        return sb.toString();
    }

