package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class SettableAnyPropertyTest {

    // Test class with Map field without initialization
    public static class AnySetterMap {
        @JsonAnySetter
        public Map<String, String> other;
    }

    // Test class with LinkedHashMap field without initialization
    public static class AnySetterLinkedHashMap {
        @JsonAnySetter
        public LinkedHashMap<String, String> other;
    }

    // Test class with HashMap field without initialization
    public static class AnySetterHashMap {
        @JsonAnySetter
        public HashMap<String, String> other;
    }

    @Test
    public void testAnySetterOnNullMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";

        AnySetterMap result = mapper.readValue(json, AnySetterMap.class);
        assertNotNull("Map should not be null", result.other);
        assertEquals(2, result.other.size());
        assertEquals("value1", result.other.get("key1"));
        assertEquals("value2", result.other.get("key2"));
    }

    @Test
    public void testAnySetterOnNullLinkedHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";

        AnySetterLinkedHashMap result = mapper.readValue(json, AnySetterLinkedHashMap.class);
        assertNotNull("LinkedHashMap should not be null", result.other);
        assertEquals(2, result.other.size());
        assertEquals("value1", result.other.get("key1"));
        assertEquals("value2", result.other.get("key2"));
        // Additionally, check that it's a LinkedHashMap (order preserved)
        assertTrue(result.other instanceof LinkedHashMap);
    }

    @Test
    public void testAnySetterOnNullHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";

        AnySetterHashMap result = mapper.readValue(json, AnySetterHashMap.class);
        assertNotNull("HashMap should not be null", result.other);
        assertEquals(2, result.other.size());
        assertEquals("value1", result.other.get("key1"));
        assertEquals("value2", result.other.get("key2"));
        assertTrue(result.other instanceof HashMap);
    }

    // Test that existing non-null map works as before
    public static class AnySetterMapInitialized {
        @JsonAnySetter
        public Map<String, String> other = new LinkedHashMap<>();
    }

    @Test
    public void testAnySetterOnInitializedMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";

        AnySetterMapInitialized result = mapper.readValue(json, AnySetterMapInitialized.class);
        assertNotNull(result.other);
        assertEquals(2, result.other.size());
        assertEquals("value1", result.other.get("key1"));
        assertEquals("value2", result.other.get("key2"));
    }
}

