package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.json.JsonMapper;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.Objects;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class CollectionDeserializerNullSkipTest {

    // Test for READ_UNKNOWN_ENUM_VALUES_AS_NULL
    @Test
    public void testSkipNullFromUnknownEnum() throws Exception {
        ObjectMapper mapper = JsonMapper.builder()
                .defaultSetterInfo(JsonSetter.Value.forContentNulls(Nulls.SKIP))
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
                .build();

        String json = "{ \"types\" : [\"TWO\", \"THREE\"] }";
        Data data = mapper.readValue(json, Data.class);
        // Expect only "TWO" in the list, "THREE" becomes null and should be skipped
        assertEquals(1, data.getTypes().size());
        assertEquals(Type.TWO, data.getTypes().get(0));
    }

    // Test for FAIL_ON_INVALID_SUBTYPE (disabled)
    @Test
    public void testSkipNullFromUnknownSubtype() throws Exception {
        ObjectMapper mapper = JsonMapper.builder()
                .defaultSetterInfo(JsonSetter.Value.forContentNulls(Nulls.SKIP))
                .disable(DeserializationFeature.FAIL_ON_INVALID_SUBTYPE)
                .build();

        String json = "[ { \"type\" : \"TYPE1\"  }, { \"type\" : \"TYPE2\"  } ]";
        List<DataAbstract> actual = mapper.readValue(json, new TypeReference<List<DataAbstract>>() {});

        DataType1 data = new DataType1();
        data.setType("TYPE1");
        List<DataAbstract> expected = Arrays.asList(data);
        // Expect only one element, the unknown subtype becomes null and should be skipped
        assertEquals(expected, actual);
    }

    // Helper classes for enum test
    static class Data {
        private List<Type> types;

        public List<Type> getTypes() {
            return types;
        }

        public void setTypes(List<Type> types) {
            this.types = types;
        }
    }

    enum Type {
        ONE, TWO
    }

    // Helper classes for subtype test
    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type", include = JsonTypeInfo.As.EXISTING_PROPERTY, visible = true)
    @JsonSubTypes(value = { @JsonSubTypes.Type(value = DataType1.class, names = { "TYPE1" }) })
    static abstract class DataAbstract {
        private String type;

        public String getType() {
            return type;
        }

        public void setType(String type) {
            this.type = type;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            DataAbstract that = (DataAbstract) o;
            return Objects.equals(type, that.type);
        }

        @Override
        public int hashCode() {
            return Objects.hash(type);
        }
    }

    static class DataType1 extends DataAbstract {
    }
}

