package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

public class POJOPropertyBuilderTest {

    public static class DataB {
        private int readonly;
        private int readwrite;

        public DataB() {
            readonly = 1;
            readwrite = 2;
        }

        public int getReadwrite() {
            return readwrite;
        }
        public void setReadwrite(int readwrite) {
            this.readwrite = readwrite;
        }
        public int getReadonly() {
            return readonly;
        }
    }

    @Test
    public void testRequireSettersForGettersWithFields() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.setVisibility(PropertyAccessor.ALL, Visibility.NONE);
        mapper.setVisibility(PropertyAccessor.GETTER, Visibility.PUBLIC_ONLY);
        mapper.setVisibility(PropertyAccessor.SETTER, Visibility.PUBLIC_ONLY);
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        DataB dataB = new DataB();
        String json = mapper.writeValueAsString(dataB);

        // With the fix, only readwrite should be serialized because it has both getter and setter.
        // readonly has only a getter and the field is not visible (due to ALL set to NONE),
        // so it should not be serialized.
        assertFalse("JSON should not contain 'readonly'", json.contains("\"readonly\""));
        assertTrue("JSON should contain 'readwrite'", json.contains("\"readwrite\""));
        // Optionally, check the exact JSON
        assertEquals("{\"readwrite\":2}", json);
    }
}

