package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonMappingException;
import org.junit.Test;

import static org.junit.Assert.*;

public class UnwrapSingleValueArrayTest {

    public enum MyEnum {
        FOO("FOO"),
        BAR("BAR");

        private final String value;

        MyEnum(String value) {
            this.value = value;
        }

        @JsonCreator
        public static MyEnum fromValue(String text) {
            for (MyEnum e : values()) {
                if (e.value.equals(text)) {
                    return e;
                }
            }
            throw new IllegalArgumentException("Unknown value: " + text);
        }
    }

    @Test
    public void testEnumWithSingleValueArray() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        MyEnum result1 = mapper.readValue("\"FOO\"", MyEnum.class);
        assertEquals(MyEnum.FOO, result1);

        MyEnum result2 = mapper.readValue("[\"FOO\"]", MyEnum.class);
        assertEquals(MyEnum.FOO, result2);

        MyEnum result3 = mapper.readValue("[\"BAR\"]", MyEnum.class);
        assertEquals(MyEnum.BAR, result3);
    }

    public static class SimpleBean {
        public String value;

        public SimpleBean() {}

        public SimpleBean(String v) {
            value = v;
        }
    }

    @Test(expected = JsonMappingException.class)
    public void testNestedArrayWithUnwrap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        mapper.readValue("[[\"value\"]]", SimpleBean.class);
    }

    @Test
    public void testSingleElementArrayForPojo() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        SimpleBean bean = mapper.readValue("[\"test\"]", SimpleBean.class);
        assertNotNull(bean);
        assertEquals("test", bean.value);
    }
}

