package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.BaseMapTest;

import java.io.IOException;
import java.util.Date;

public class StdDeserializerNestedArrayTest extends BaseMapTest
{
    private final ObjectMapper MAPPER = new ObjectMapper()
        .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

    // Helper method to test nested array for a given type
    private void testNestedArrayForType(Class<?> targetType, String nestedArrayJson) throws Exception {
        try {
            MAPPER.readValue(nestedArrayJson, targetType);
            fail("Expected an exception for nested array with " + targetType.getSimpleName());
        } catch (MismatchedInputException e) {
            // Expected: nested Arrays not allowed with UNWRAP_SINGLE_VALUE_ARRAYS
            verifyException(e, "nested Arrays not allowed");
        }
    }

    // Test for boolean
    public void testNestedArrayBoolean() throws Exception {
        testNestedArrayForType(boolean.class, "[[true]]");
        testNestedArrayForType(Boolean.class, "[[false]]");
    }

    // Test for byte
    public void testNestedArrayByte() throws Exception {
        testNestedArrayForType(byte.class, "[[42]]");
        testNestedArrayForType(Byte.class, "[[-128]]");
    }

    // Test for short
    public void testNestedArrayShort() throws Exception {
        testNestedArrayForType(short.class, "[[1000]]");
        testNestedArrayForType(Short.class, "[[-1000]]");
    }

    // Test for int
    public void testNestedArrayInt() throws Exception {
        testNestedArrayForType(int.class, "[[123456]]");
        testNestedArrayForType(Integer.class, "[[-123456]]");
    }

    // Test for long
    public void testNestedArrayLong() throws Exception {
        testNestedArrayForType(long.class, "[[9876543210]]");
        testNestedArrayForType(Long.class, "[[-9876543210]]");
    }

    // Test for float
    public void testNestedArrayFloat() throws Exception {
        testNestedArrayForType(float.class, "[[3.14]]");
        testNestedArrayForType(Float.class, "[[-3.14]]");
    }

    // Test for double
    public void testNestedArrayDouble() throws Exception {
        testNestedArrayForType(double.class, "[[2.71828]]");
        testNestedArrayForType(Double.class, "[[-2.71828]]");
    }

    // Test for java.util.Date
    public void testNestedArrayDate() throws Exception {
        // Date deserialization depends on format; use a simple timestamp
        testNestedArrayForType(Date.class, "[[1000000]]");
        // Also test with string date if needed, but the nested array is the key.
        // We'll just use a number for simplicity.
    }

    // Additionally, test that a single-level array still works (unwrapping)
    public void testSingleArrayUnwrapping() throws Exception {
        assertEquals(Boolean.TRUE, MAPPER.readValue("[true]", boolean.class));
        assertEquals(Integer.valueOf(42), MAPPER.readValue("[42]", int.class));
        assertEquals(3.14f, MAPPER.readValue("[3.14]", float.class), 0.001f);
        // Date from timestamp array
        Date date = MAPPER.readValue("[1000000]", Date.class);
        assertEquals(1000000L, date.getTime());
    }

    // Test that without UNWRAP_SINGLE_VALUE_ARRAYS, nested array should also fail but with different error?
    // Actually, without the feature, a nested array would be considered as type mismatch.
    // We can optionally test that, but it's not required for the patch.
    // However, we should ensure that the feature is required for the new check.
    // So let's test that without the feature, we get a different error (not about nested arrays).
    public void testNestedArrayWithoutFeature() throws Exception {
        ObjectMapper mapper = new ObjectMapper()
            .disable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("[[true]]", boolean.class);
            fail("Expected an exception without UNWRAP_SINGLE_VALUE_ARRAYS");
        } catch (MismatchedInputException e) {
            // Without the feature, the error message is different (not about nested arrays)
            // We just want to ensure no infinite recursion occurs.
            // So we don't assert the message.
        }
    }

    // Test the helper method handleNestedArrayForSingle via a custom deserializer?
    // We can also test that the method is called by using a mock, but it's not necessary.
    // Instead, we can test that the error message contains the expected text.
    public void testErrorMessage() throws Exception {
        try {
            MAPPER.readValue("[[true]]", boolean.class);
            fail("Expected an exception");
        } catch (MismatchedInputException e) {
            String msg = e.getMessage();
            assertTrue("Message should mention 'nested Arrays'", msg.contains("nested Arrays"));
            assertTrue("Message should mention 'UNWRAP_SINGLE_VALUE_ARRAYS'", 
                msg.contains("UNWRAP_SINGLE_VALUE_ARRAYS"));
        }
    }

    // Edge case: three levels of nesting should also be caught (the check is on the second level)
    public void testThreeLevelNestedArray() throws Exception {
        // The check is triggered when we see START_ARRAY after the first array.
        // So for three levels, we have [[[...]]]. The first array is unwrapped, then the next token is START_ARRAY again.
        // That should trigger the same error.
        testNestedArrayForType(boolean.class, "[[[true]]]");
        testNestedArrayForType(int.class, "[[[42]]]");
    }

    // Test that the fix works for custom deserializers that extend StdDeserializer and use _parseXxxPrimitive methods.
    // We can create a simple custom deserializer for a wrapper type and test it.
    static class CustomBooleanDeserializer extends StdDeserializer<Boolean> {
        public CustomBooleanDeserializer() { super(Boolean.class); }
        @Override
        public Boolean deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            if (p.currentToken() == JsonToken.START_ARRAY && ctxt.isEnabled(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS)) {
                p.nextToken();
                if (p.currentToken() == JsonToken.START_ARRAY) {
                    return (Boolean) handleNestedArrayForSingle(p, ctxt);
                }
                Boolean value = deserialize(p, ctxt);
                _verifyEndArrayForSingle(p, ctxt);
                return value;
            }
            return p.getBooleanValue();
        }
    }

    public void testCustomDeserializerWithNestedArray() throws Exception {
        SimpleModule module = new SimpleModule();
        module.addDeserializer(Boolean.class, new CustomBooleanDeserializer());
        ObjectMapper mapper = new ObjectMapper()
            .registerModule(module)
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("[[true]]", Boolean.class);
            fail("Expected an exception for custom deserializer");
        } catch (MismatchedInputException e) {
            verifyException(e, "nested Arrays not allowed");
        }
    }
}

