    // We can create a simple custom deserializer for a wrapper type and test it.
    static class CustomBooleanDeserializer extends StdDeserializer<Boolean> {
        public CustomBooleanDeserializer() { super(Boolean.class); }
        @Override
        public Boolean deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            if (p.currentToken() == JsonToken.START_ARRAY && ctxt.isEnabled(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS)) {
                p.nextToken();
                if (p.currentToken() == JsonToken.START_ARRAY) {
                    return (Boolean) handleNestedArrayForSingle(p, ctxt);
                }
                Boolean value = deserialize(p, ctxt);
                _verifyEndArrayForSingle(p, ctxt);
                return value;
            }
            return p.getBooleanValue();
        }
    }

    public void testCustomDeserializerWithNestedArray() throws Exception {
        SimpleModule module = new SimpleModule();
        module.addDeserializer(Boolean.class, new CustomBooleanDeserializer());
        ObjectMapper mapper = new ObjectMapper()
            .registerModule(module)
            .enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        try {
            mapper.readValue("[[true]]", Boolean.class);
            fail("Expected an exception for custom deserializer");
        } catch (MismatchedInputException e) {
            verifyException(e, "nested Arrays not allowed");
        }
    }
}

