        assertNull(mapper.readValue("42", Float.class));
        assertNull(mapper.readValue("42", Double.class));
        assertNull(mapper.readValue("42", BigDecimal.class));

        // Change to AsEmpty
        mapper.coercionConfigFor(LogicalType.Float)
