package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedParameter;
import com.fasterxml.jackson.databind.introspect.NopAnnotationIntrospector;
import com.fasterxml.jackson.databind.BaseMapTest;

import java.lang.annotation.Annotation;

public class AnnotationIntrospectorPairMergeTest extends BaseMapTest
{
    // Custom introspector that returns a PropertyName with empty string for local name
    static class IntrospectorEmptyName extends NopAnnotationIntrospector
    {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            // Return a PropertyName with empty string for local name, and a namespace
            return new PropertyName("", "http://example.com/ns1");
        }
    }

    // Custom introspector that returns a PropertyName with non-empty local name and namespace
    static class IntrospectorWithName extends NopAnnotationIntrospector
    {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return new PropertyName("actualName", "http://example.com/ns2");
        }
    }

    // Introspector that returns null
    static class IntrospectorNull extends NopAnnotationIntrospector
    {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return null;
        }
    }

    // Introspector that returns USE_DEFAULT
    static class IntrospectorUseDefault extends NopAnnotationIntrospector
    {
        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return PropertyName.USE_DEFAULT;
        }
    }

    // Test PropertyName.merge directly
    public void testPropertyNameMerge() {
        // Both null -> null
        assertNull(PropertyName.merge(null, null));

        // First null, second non-null
        PropertyName pn = new PropertyName("test");
        assertSame(pn, PropertyName.merge(null, pn));

        // First non-null, second null
        assertSame(pn, PropertyName.merge(pn, null));

        // Both non-null, first has empty local name, second has non-empty
        PropertyName emptySimple = new PropertyName("", "ns1");
        PropertyName withSimple = new PropertyName("simple", "ns2");
        PropertyName merged = PropertyName.merge(emptySimple, withSimple);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace()); // ns1 is non-empty, so it takes precedence

        // First has non-empty local name, second has empty local name
        merged = PropertyName.merge(withSimple, emptySimple);
        assertEquals("simple", merged.getSimpleName()); // first's non-empty takes precedence
        assertEquals("ns2", merged.getNamespace());

        // First has empty namespace, second has non-empty namespace
        PropertyName emptyNs = new PropertyName("name", "");
        PropertyName withNs = new PropertyName("name", "ns");
        merged = PropertyName.merge(emptyNs, withNs);
        assertEquals("name", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace()); // second's namespace is non-empty, but first's namespace is empty, so second's is used

        // First has non-empty namespace, second has empty namespace
        merged = PropertyName.merge(withNs, emptyNs);
        assertEquals("name", merged.getSimpleName());
        assertEquals("ns", merged.getNamespace()); // first's non-empty takes precedence

        // Both have non-empty, first takes precedence
        PropertyName pn1 = new PropertyName("name1", "ns1");
        PropertyName pn2 = new PropertyName("name2", "ns2");
        merged = PropertyName.merge(pn1, pn2);
        assertEquals("name1", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }

    // Test AnnotationIntrospectorPair.findNameForSerialization with merging
    public void testFindNameForSerializationMerge() throws Exception
    {
        // Create a dummy Annotated object (we'll use an AnnotatedField from a simple class)
        @SuppressWarnings("serial")
        class SimpleBean {
            public int value;
        }
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig().introspectClassAnnotations(SimpleBean.class);
        AnnotatedClass ac = beanDesc.getClassInfo();
        AnnotatedField field = ac.fields().iterator().next();

        // Case 1: Primary returns empty local name, secondary returns non-empty
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new IntrospectorEmptyName(),
                new IntrospectorWithName());
        PropertyName result = pair.findNameForSerialization(field);
        assertNotNull(result);
        // According to merge logic: primary's local name is empty, so secondary's non-empty should be used.
        // primary's namespace is non-empty, so it should be used.
        assertEquals("actualName", result.getSimpleName());
        assertEquals("http://example.com/ns1", result.getNamespace());

        // Case 2: Primary returns null, secondary returns non-empty
        pair = new AnnotationIntrospectorPair(
                new IntrospectorNull(),
                new IntrospectorWithName());
        result = pair.findNameForSerialization(field);
        assertNotNull(result);
        assertEquals("actualName", result.getSimpleName());
        assertEquals("http://example.com/ns2", result.getNamespace());

        // Case 3: Primary returns USE_DEFAULT, secondary returns non-empty
        pair = new AnnotationIntrospectorPair(
                new IntrospectorUseDefault(),
                new IntrospectorWithName());
        result = pair.findNameForSerialization(field);
        assertNotNull(result);
        // USE_DEFAULT is a special PropertyName instance with empty string for both.
        // According to merge, secondary's non-empty should be used.
        assertEquals("actualName", result.getSimpleName());
        assertEquals("http://example.com/ns2", result.getNamespace());

        // Case 4: Primary returns non-empty, secondary returns empty local name
        pair = new AnnotationIntrospectorPair(
                new IntrospectorWithName(),
                new IntrospectorEmptyName());
        result = pair.findNameForSerialization(field);
        assertNotNull(result);
        assertEquals("actualName", result.getSimpleName());
        assertEquals("http://example.com/ns2", result.getNamespace());

        // Case 5: Both return null -> null
        pair = new AnnotationIntrospectorPair(
                new IntrospectorNull(),
                new IntrospectorNull());
        result = pair.findNameForSerialization(field);
        assertNull(result);
    }

    // Similarly test findNameForDeserialization, findWrapperName, etc.
    // We'll test one more method to ensure merging is applied.
    public void testFindWrapperNameMerge() throws Exception
    {
        // Create a dummy Annotated object
        @SuppressWarnings("serial")
        class SimpleBean {
            public int value;
        }
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig().introspectClassAnnotations(SimpleBean.class);
        AnnotatedClass ac = beanDesc.getClassInfo();
        AnnotatedMethod method = ac.findMethod("toString", null); // just to get an Annotated

        // We need introspectors that override findWrapperName
        class IntrospectorWrapper1 extends NopAnnotationIntrospector {
            @Override
            public PropertyName findWrapperName(Annotated a) {
                return new PropertyName("", "ns1");
            }
        }
        class IntrospectorWrapper2 extends NopAnnotationIntrospector {
            @Override
            public PropertyName findWrapperName(Annotated a) {
                return new PropertyName("wrapper", "ns2");
            }
        }

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(
                new IntrospectorWrapper1(),
                new IntrospectorWrapper2());
        PropertyName result = pair.findWrapperName(method);
        assertNotNull(result);
        assertEquals("wrapper", result.getSimpleName()); // secondary's non-empty local name
        assertEquals("ns1", result.getNamespace()); // primary's non-empty namespace
    }

    // Test findRootName as well
    public void testFindRootNameMerge() throws Exception
    {
        class IntrospectorRoot1 extends NopAnnotationIntrospector {
            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("", "ns1");
            }
        }
        class IntrospectorRoot2 extends NopAnnotationIntrospector {
            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("root", "ns2");
            }
        }

