package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper.DefaultTyping;
import com.fasterxml.jackson.databind.jsontype.impl.LaissezFaireSubTypeValidator;
import com.fasterxml.jackson.databind.json.JsonMapper;
import org.junit.Test;

import java.io.IOException;
import java.util.Objects;

import static org.junit.Assert.*;

public class ObjectMapperDefaultTypingNonFinalAndEnumsTest {

    // Test enum for polymorphic serialization
    public enum Frequency {
        DAILY, WEEKLY, MONTHLY
    }

    // Test class containing enum field
    public static class EnumContainer {
        public Frequency frequency;

        public EnumContainer() {}
        public EnumContainer(Frequency f) { frequency = f; }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            EnumContainer that = (EnumContainer) o;
            return frequency == that.frequency;
        }

        @Override
        public int hashCode() {
            return Objects.hash(frequency);
        }
    }

    @Test
    public void testNonFinalAndEnumsDefaultTypingWithEnum() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // Test serialization/deserialization of enum directly
        Frequency original = Frequency.DAILY;
        String json = mapper.writeValueAsString(original);
        Frequency deserialized = mapper.readValue(json, Frequency.class);
        assertEquals(original, deserialized);

        // Verify type information is included
        assertTrue(json.contains("Frequency"));
        assertTrue(json.contains("DAILY"));
    }

    @Test
    public void testNonFinalAndEnumsDefaultTypingWithEnumInContainer() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // Test with enum inside a container class
        EnumContainer original = new EnumContainer(Frequency.WEEKLY);
        String json = mapper.writeValueAsString(original);
        EnumContainer deserialized = mapper.readValue(json, EnumContainer.class);
        assertEquals(original, deserialized);
        assertEquals(Frequency.WEEKLY, deserialized.frequency);
    }

    @Test
    public void testNonFinalAndEnumsDefaultTypingWithEnumArray() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // Test with array of enums
        Frequency[] original = {Frequency.DAILY, Frequency.MONTHLY};
        String json = mapper.writeValueAsString(original);
        Frequency[] deserialized = mapper.readValue(json, Frequency[].class);
        assertArrayEquals(original, deserialized);
    }

    @Test
    public void testNonFinalAndEnumsDefaultTypingWithEnumList() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // Test with list of enums
        java.util.List<Frequency> original = java.util.Arrays.asList(Frequency.DAILY, Frequency.WEEKLY);
        String json = mapper.writeValueAsString(original);
        java.util.List<Frequency> deserialized = mapper.readValue(json, 
                new TypeReference<java.util.List<Frequency>>() {});
        assertEquals(original, deserialized);
    }

    @Test
    public void testNonFinalAndEnumsDoesNotIncludeFinalNonEnumTypes() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // String is final and not an enum - should not have type info
        String original = "test";
        String json = mapper.writeValueAsString(original);
        // String should be serialized without type wrapper
        assertEquals("\"test\"", json);

        String deserialized = mapper.readValue(json, String.class);
        assertEquals(original, deserialized);
    }

    @Test
    public void testNonFinalAndEnumsIncludesNonFinalTypes() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // EnumContainer is non-final - should have type info
        EnumContainer original = new EnumContainer(Frequency.DAILY);
        String json = mapper.writeValueAsString(original);
        assertTrue(json.contains("EnumContainer"));

        EnumContainer deserialized = mapper.readValue(json, EnumContainer.class);
        assertEquals(original, deserialized);
    }

    @Test
    public void testNonFinalAndEnumsWithWrapperObject() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_OBJECT)
                .build();

        // Test with WRAPPER_OBJECT format
        Frequency original = Frequency.MONTHLY;
        String json = mapper.writeValueAsString(original);
        Frequency deserialized = mapper.readValue(json, Frequency.class);
        assertEquals(original, deserialized);

        // Should contain type information as object wrapper
        assertTrue(json.contains("Frequency"));
        assertTrue(json.contains("MONTHLY"));
    }

    @Test
    public void testNonFinalAndEnumsWithPropertyFormat() throws IOException {
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.PROPERTY)
                .build();

        // Test with PROPERTY format
        Frequency original = Frequency.WEEKLY;
        String json = mapper.writeValueAsString(original);
        Frequency deserialized = mapper.readValue(json, Frequency.class);
        assertEquals(original, deserialized);
    }

    @Test
    public void testNonFinalAndEnumsWithExistingEnumDeserializer() throws IOException {
        // This test specifically addresses the issue #3569 where
        // FactoryBasedEnumDeserializer failed with WRAPPER_ARRAY format
        ObjectMapper mapper = JsonMapper.builder()
                .activateDefaultTyping(LaissezFaireSubTypeValidator.instance, 
                        DefaultTyping.NON_FINAL_AND_ENUMS,
                        JsonTypeInfo.As.WRAPPER_ARRAY)
                .build();

        // Simulate the exact scenario from the issue
        String jsonWithWrapperArray = "[\"" + Frequency.class.getName() + "\",\"DAILY\"]";
        Frequency deserialized = mapper.readValue(jsonWithWrapperArray, Frequency.class);
        assertEquals(Frequency.DAILY, deserialized);
    }
}

