package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.math.BigDecimal;

import static org.junit.Assert.*;

public class NumberDeserializersCoercionTest {

    // Helper classes for deserialization
    static class FloatWrapper {
        public Float value;
    }

    static class DoubleWrapper {
        public Double value;
    }

    static class BigDecimalWrapper {
        public BigDecimal value;
    }

    static class PrimitiveFloatWrapper {
        public float value;
    }

    static class PrimitiveDoubleWrapper {
        public double value;
    }

    @Test
    public void testIntToFloatCoercionFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test wrapper Float
        try {
            mapper.readValue("{\"value\": 123}", FloatWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test primitive float
        try {
            mapper.readValue("{\"value\": 123}", PrimitiveFloatWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test wrapper Double
        try {
            mapper.readValue("{\"value\": 123}", DoubleWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test primitive double
        try {
            mapper.readValue("{\"value\": 123}", PrimitiveDoubleWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }

        // Test BigDecimal
        try {
            mapper.readValue("{\"value\": 123}", BigDecimalWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            // expected
        }
    }

    @Test
    public void testIntToFloatCoercionAsNull() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Wrapper Float: should become null
        FloatWrapper fw = mapper.readValue("{\"value\": 123}", FloatWrapper.class);
        assertNull(fw.value);

        // Primitive float: should become 0.0
        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 123}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);

        // Wrapper Double: should become null
        DoubleWrapper dw = mapper.readValue("{\"value\": 123}", DoubleWrapper.class);
        assertNull(dw.value);

        // Primitive double: should become 0.0
        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 123}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0, pdw.value, 0.0);

        // BigDecimal: should become null (since getNullValue returns null for BigDecimal?)
        // Actually, BigDecimal is a reference type, so getNullValue returns null.
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 123}", BigDecimalWrapper.class);
        assertNull(bdw.value);
    }

    @Test
    public void testIntToFloatCoercionAsEmpty() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Wrapper Float: should become empty value (0.0f? Actually getEmptyValue for Float returns 0.0f)
        FloatWrapper fw = mapper.readValue("{\"value\": 123}", FloatWrapper.class);
        assertEquals(Float.valueOf(0.0f), fw.value);

        // Primitive float: should become 0.0
        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 123}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);

        // Wrapper Double: should become empty value (0.0)
        DoubleWrapper dw = mapper.readValue("{\"value\": 123}", DoubleWrapper.class);
        assertEquals(Double.valueOf(0.0), dw.value);

        // Primitive double: should become 0.0
        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 123}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0, pdw.value, 0.0);

        // BigDecimal: should become empty value (BigDecimal.ZERO)
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 123}", BigDecimalWrapper.class);
        assertEquals(BigDecimal.ZERO, bdw.value);
    }

    @Test
    public void testIntToFloatCoercionDefault() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        // Default coercion is to convert, so we don't change anything.

        // All should convert integer to float/double/BigDecimal without issue.
        FloatWrapper fw = mapper.readValue("{\"value\": 123}", FloatWrapper.class);
        assertEquals(123.0f, fw.value, 0.0f);

        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 123}", PrimitiveFloatWrapper.class);
        assertEquals(123.0f, pfw.value, 0.0f);

        DoubleWrapper dw = mapper.readValue("{\"value\": 123}", DoubleWrapper.class);
        assertEquals(123.0, dw.value, 0.0);

        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 123}", PrimitiveDoubleWrapper.class);
        assertEquals(123.0, pdw.value, 0.0);

        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 123}", BigDecimalWrapper.class);
        assertEquals(BigDecimal.valueOf(123), bdw.value);
    }

    // Additional test: ensure that floating-point numbers still work when coercion is set to fail (only integers are affected)
    @Test
    public void testFloatInputWithCoercionFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Floating-point numbers should still be accepted.
        FloatWrapper fw = mapper.readValue("{\"value\": 123.5}", FloatWrapper.class);
        assertEquals(123.5f, fw.value, 0.0f);

        DoubleWrapper dw = mapper.readValue("{\"value\": 123.5}", DoubleWrapper.class);
        assertEquals(123.5, dw.value, 0.0);

        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 123.5}", BigDecimalWrapper.class);
        assertEquals(new BigDecimal("123.5"), bdw.value);
    }

    // Test null token: should still be handled correctly (null -> null for wrappers, 0 for primitives)
    @Test
    public void testNullToken() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        FloatWrapper fw = mapper.readValue("{\"value\": null}", FloatWrapper.class);
        assertNull(fw.value);

        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": null}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);

        DoubleWrapper dw = mapper.readValue("{\"value\": null}", DoubleWrapper.class);
        assertNull(dw.value);

        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": null}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0, pdw.value, 0.0);

        BigDecimalWrapper bdw = mapper.readValue("{\"value\": null}", BigDecimalWrapper.class);
        assertNull(bdw.value);
    }
}

