package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedClassResolver;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class EnumValuesTest {
    enum NullToStringEnum {
        ALPHA("A"),
        BETA("B"),
        UNDEFINED(null);

        private final String s;

        NullToStringEnum(String s) {
            this.s = s;
        }

        @Override
        public String toString() {
            return s;
        }
    }

    @Test
    public void testConstructFromToStringWithNullToString() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        // This should not throw after the patch
        assertDoesNotThrow(() -> mapper.writerFor(NullToStringEnum.class));

        // Verify serialization works correctly
        ObjectWriter writer = mapper.writerFor(NullToStringEnum.class);
        assertDoesNotThrow(() -> writer.writeValueAsString(NullToStringEnum.ALPHA));
        assertDoesNotThrow(() -> writer.writeValueAsString(NullToStringEnum.UNDEFINED));

        // The actual serialized values should use enum names, not toString()
        assertEquals("\"ALPHA\"", mapper.writeValueAsString(NullToStringEnum.ALPHA));
        assertEquals("\"UNDEFINED\"", mapper.writeValueAsString(NullToStringEnum.UNDEFINED));
    }

    @Test
    public void testConstructFromToStringDirectly() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        JavaType enumType = mapper.getTypeFactory().constructType(NullToStringEnum.class);
        AnnotatedClass annotatedClass = AnnotatedClassResolver.resolve(
                mapper.getSerializationConfig(), 
                enumType, 
                mapper.getSerializationConfig()
        );

        // This method is called internally when building enum serializer
        // Fixed: Use the correct method signature with 2 parameters
        EnumValues values = EnumValues.constructFromToString(
                mapper.getSerializationConfig(), 
                annotatedClass
        );

        // Should not have null entries - null toString should be coerced to empty string
        assertNotNull(values);
        // Verify we can get serialized string for all enum values without exception
        for (NullToStringEnum e : NullToStringEnum.values()) {
            assertDoesNotThrow(() -> values.serializedValueFor(e));
        }
    }
}

