import java.util.OptionalInt;
import java.util.OptionalLong;
import java.util.OptionalDouble;
import java.util.Optional;

import static org.junit.Assert.*;
import org.junit.Test;

public class BeanUtilTest {

    // Test the new isJava8OptionalClass methods
    @Test
    public void testIsJava8OptionalClass() {
        // Test with class objects
        assertTrue(BeanUtil.isJava8OptionalClass(OptionalInt.class));
        assertTrue(BeanUtil.isJava8OptionalClass(OptionalLong.class));
        assertTrue(BeanUtil.isJava8OptionalClass(OptionalDouble.class));
        assertTrue(BeanUtil.isJava8OptionalClass(Optional.class));

        // Test with non-optional classes
        assertFalse(BeanUtil.isJava8OptionalClass(String.class));
        assertFalse(BeanUtil.isJava8OptionalClass(Integer.class));
        assertFalse(BeanUtil.isJava8OptionalClass(java.time.LocalDate.class));
    }

    // Test checkUnsupportedType for Java 8 optional classes
    @Test
    public void testCheckUnsupportedTypeForOptional() {
        // Use the method directly with a JavaType
        ObjectMapper mapper = new ObjectMapper();
        JavaType optionalIntType = mapper.constructType(OptionalInt.class);
        String msg = BeanUtil.checkUnsupportedType(optionalIntType);
        assertNotNull(msg);
        assertTrue(msg.contains("Java 8 optional"));
        assertTrue(msg.contains("jackson-datatype-jdk8"));

        JavaType optionalType = mapper.constructType(Optional.class);
        msg = BeanUtil.checkUnsupportedType(optionalType);
        assertNotNull(msg);
        assertTrue(msg.contains("Java 8 optional"));
        assertTrue(msg.contains("jackson-datatype-jdk8"));

        // Non-optional type should return null
        JavaType stringType = mapper.constructType(String.class);
        assertNull(BeanUtil.checkUnsupportedType(stringType));
    }

    // Integration test: try to deserialize a class with OptionalInt field without the module
    @Test
    public void testDeserializeOptionalIntWithoutModule() {
        ObjectMapper mapper = new ObjectMapper();
        // Disable the feature that tries to set accessible, to see if the new check kicks in first?
        // Actually, we want to see if the new check prevents the InaccessibleObjectException.
        // So we don't disable anything.
        String json = "{\"value\":123}";
        try {
            mapper.readValue(json, Data.class);
            fail("Expected JsonMappingException");
        } catch (JsonMappingException e) {
            // The exception should be due to unsupported type
            // The message should contain the helpful text
            String message = e.getMessage();
            assertTrue("Message should mention 'Java 8 optional'", 
                message.contains("Java 8 optional"));
            assertTrue("Message should mention 'jackson-datatype-jdk8'", 
                message.contains("jackson-datatype-jdk8"));
        } catch (Exception e) {
            fail("Expected JsonMappingException, got " + e.getClass().getName());
        }
    }

    // Similar test for Optional
    @Test
    public void testDeserializeOptionalWithoutModule() {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"value\":\"test\"}";
        try {
            mapper.readValue(json, DataWithOptional.class);
            fail("Expected JsonMappingException");
        } catch (JsonMappingException e) {
            String message = e.getMessage();
            assertTrue(message.contains("Java 8 optional"));
            assertTrue(message.contains("jackson-datatype-jdk8"));
        } catch (Exception e) {
            fail("Expected JsonMappingException, got " + e.getClass().getName());
        }
    }

    // Helper classes for testing
    public static class Data {
        private OptionalInt value;
        public Data() { }
        public void setValue(OptionalInt i) { this.value = i; }
        public OptionalInt getValue() { return this.value; }
    }

    public static class DataWithOptional {
        private Optional<String> value;
        public DataWithOptional() { }
        public void setValue(Optional<String> v) { this.value = v; }
        public Optional<String> getValue() { return this.value; }
    }
}

