package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.InvalidFormatException;
import org.junit.Test;

import static org.junit.Assert.*;

public class EnumDeserializerTest {

    enum Color {
        RED, BLUE
    }

    static class BookWithAnnotationDisabled {
        @JsonFormat(without = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        @JsonProperty("color")
        private Color color;

        public Color getColor() {
            return color;
        }

        public void setColor(Color color) {
            this.color = color;
        }
    }

    static class BookWithAnnotationEnabled {
        @JsonFormat(with = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        @JsonProperty("color")
        private Color color;

        public Color getColor() {
            return color;
        }

        public void setColor(Color color) {
            this.color = color;
        }
    }

    static class BookWithoutAnnotation {
        @JsonProperty("color")
        private Color color;

        public Color getColor() {
            return color;
        }

        public void setColor(Color color) {
            this.color = color;
        }
    }

    @Test
    public void testAnnotationWithoutOverridesGlobalEnabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Annotation should override global setting to false
        try {
            objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithAnnotationDisabled.class);
            fail("Expected InvalidFormatException");
        } catch (InvalidFormatException e) {
            // Expected: annotation's without=READ_UNKNOWN_ENUM_VALUES_AS_NULL should disable null return
            assertTrue(e.getMessage().contains("not one of the values accepted for Enum class"));
        }
    }

    @Test
    public void testAnnotationWithoutWithGlobalDisabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .disable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Annotation without=READ_UNKNOWN_ENUM_VALUES_AS_NULL with global disabled should also throw
        try {
            objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithAnnotationDisabled.class);
            fail("Expected InvalidFormatException");
        } catch (InvalidFormatException e) {
            assertTrue(e.getMessage().contains("not one of the values accepted for Enum class"));
        }
    }

    @Test
    public void testAnnotationWithOverridesGlobalDisabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .disable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Annotation should override global setting to true
        BookWithAnnotationEnabled book = objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithAnnotationEnabled.class);
        assertNull(book.getColor());
    }

    @Test
    public void testAnnotationWithWithGlobalEnabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Annotation with=READ_UNKNOWN_ENUM_VALUES_AS_NULL with global enabled should return null
        BookWithAnnotationEnabled book = objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithAnnotationEnabled.class);
        assertNull(book.getColor());
    }

    @Test
    public void testNoAnnotationWithGlobalEnabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // No annotation, global enabled should return null
        BookWithoutAnnotation book = objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithoutAnnotation.class);
        assertNull(book.getColor());
    }

    @Test
    public void testNoAnnotationWithGlobalDisabled() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .disable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // No annotation, global disabled should throw
        try {
            objectMapper.readValue("{\"color\":\"WHITE\"}", BookWithoutAnnotation.class);
            fail("Expected InvalidFormatException");
        } catch (InvalidFormatException e) {
            assertTrue(e.getMessage().contains("not one of the values accepted for Enum class"));
        }
    }

    @Test
    public void testValidEnumValueWithAnnotation() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Valid enum value should work regardless of annotation
        BookWithAnnotationDisabled book = objectMapper.readValue("{\"color\":\"RED\"}", BookWithAnnotationDisabled.class);
        assertEquals(Color.RED, book.getColor());
    }

    @Test
    public void testNullValueWithAnnotation() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper()
                .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Null JSON value should deserialize to null
        BookWithAnnotationDisabled book = objectMapper.readValue("{\"color\":null}", BookWithAnnotationDisabled.class);
        assertNull(book.getColor());
    }
}

