package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonNodeWithObjectArrayPropertyTest {

    private final ObjectMapper mapper = new ObjectMapper();

    @Test
    public void testWithObjectPropertyOnObjectNode() {
        ObjectNode root = mapper.createObjectNode();

        // When property does not exist, should create new ObjectNode
        ObjectNode child1 = root.withObjectProperty("newObj");
        assertNotNull(child1);
        assertTrue(child1.isObject());
        assertSame(child1, root.get("newObj"));

        // When property exists and is ObjectNode, should return it
        ObjectNode child2 = root.withObjectProperty("newObj");
        assertSame(child1, child2);

        // When property exists and is NullNode, should replace with new ObjectNode
        root.putNull("nullProp");
        ObjectNode child3 = root.withObjectProperty("nullProp");
        assertNotNull(child3);
        assertTrue(child3.isObject());
        assertSame(child3, root.get("nullProp"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnNonObjectNode() {
        ArrayNode arrayNode = mapper.createArrayNode();
        arrayNode.withObjectProperty("prop");
    }

    @Test
    public void testWithObjectPropertyOnExistingNonObjectNonNull() {
        ObjectNode root = mapper.createObjectNode();
        root.put("text", "value");

        try {
            root.withObjectProperty("text");
            fail("Should have thrown exception for non-object, non-null existing value");
        } catch (UnsupportedOperationException e) {
            // Expected - the patch throws UnsupportedOperationException, not IllegalArgumentException
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("ObjectNode"));
            assertTrue(e.getMessage().contains("TextNode"));
        }
    }

    @Test
    public void testWithArrayPropertyOnObjectNode() {
        ObjectNode root = mapper.createObjectNode();

        // When property does not exist, should create new ArrayNode
        ArrayNode child1 = root.withArrayProperty("newArr");
        assertNotNull(child1);
        assertTrue(child1.isArray());
        assertSame(child1, root.get("newArr"));

        // When property exists and is ArrayNode, should return it
        ArrayNode child2 = root.withArrayProperty("newArr");
        assertSame(child1, child2);

        // When property exists and is NullNode, should replace with new ArrayNode
        root.putNull("nullArr");
        ArrayNode child3 = root.withArrayProperty("nullArr");
        assertNotNull(child3);
        assertTrue(child3.isArray());
        assertSame(child3, root.get("nullArr"));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnNonObjectNode() {
        ArrayNode arrayNode = mapper.createArrayNode();
        arrayNode.withArrayProperty("prop");
    }

    @Test
    public void testWithArrayPropertyOnExistingNonArrayNonNull() {
        ObjectNode root = mapper.createObjectNode();
        root.put("number", 42);

        try {
            root.withArrayProperty("number");
            fail("Should have thrown exception for non-array, non-null existing value");
        } catch (UnsupportedOperationException e) {
            // Expected - the patch throws UnsupportedOperationException, not IllegalArgumentException
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("ArrayNode"));
            assertTrue(e.getMessage().contains("IntNode"));
        }
    }

    @Test
    public void testChainingWithObjectProperty() {
        ObjectNode root = mapper.createObjectNode();
        ObjectNode child = root.withObjectProperty("child");
        child.put("name", "test");

        assertEquals("test", root.get("child").get("name").asText());
    }

    @Test
    public void testChainingWithArrayProperty() {
        ObjectNode root = mapper.createObjectNode();
        ArrayNode child = root.withArrayProperty("items");
        child.add("item1");

        assertEquals("item1", root.get("items").get(0).asText());
    }

    @Test
    public void testWithObjectPropertyAndWithArrayPropertyDoNotConflict() {
        ObjectNode root = mapper.createObjectNode();
        ObjectNode obj = root.withObjectProperty("data");
        ArrayNode arr = root.withArrayProperty("list");

        assertTrue(obj.isObject());
        assertTrue(arr.isArray());
        assertSame(obj, root.get("data"));
        assertSame(arr, root.get("list"));
    }

    @Test
    public void testWithObjectPropertyOnBaseJsonNodeThrows() {
        // Test that calling on base JsonNode (not ObjectNode) throws UnsupportedOperationException
        JsonNode node = mapper.createArrayNode(); // ArrayNode extends BaseJsonNode
        try {
            node.withObjectProperty("test");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("cannot call `withObjectProperty(String)`"));
            assertTrue(e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithArrayPropertyOnBaseJsonNodeThrows() {
        // Test that calling on base JsonNode (not ObjectNode) throws UnsupportedOperationException
        JsonNode node = mapper.createArrayNode(); // ArrayNode extends BaseJsonNode
        try {
            node.withArrayProperty("test");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("cannot call `withArrayProperty(String)`"));
            assertTrue(e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithObjectPropertyOnOtherNodeTypes() {
        // Test on other node types that aren't ObjectNode
        JsonNode textNode = mapper.getNodeFactory().textNode("test");
        try {
            textNode.withObjectProperty("test");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("TextNode"));
        }
    }

    @Test
    public void testWithArrayPropertyOnOtherNodeTypes() {
        // Test on other node types that aren't ObjectNode
        JsonNode numberNode = mapper.getNodeFactory().numberNode(123);
        try {
            numberNode.withArrayProperty("test");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("IntNode"));
        }
    }

    @Test
    public void testWithObjectPropertyMultipleLevels() {
        ObjectNode root = mapper.createObjectNode();
        ObjectNode level1 = root.withObjectProperty("level1");
        ObjectNode level2 = level1.withObjectProperty("level2");
        level2.put("value", "deep");

        assertEquals("deep", root.get("level1").get("level2").get("value").asText());
    }

    @Test
    public void testWithArrayPropertyMultipleLevels() {
        ObjectNode root = mapper.createObjectNode();
        ArrayNode level1 = root.withArrayProperty("level1");
        level1.add("item1");

        ObjectNode nestedObj = mapper.createObjectNode();
        nestedObj.put("nested", "value");
        level1.add(nestedObj);

        assertEquals("item1", root.get("level1").get(0).asText());
        assertEquals("value", root.get("level1").get(1).get("nested").asText());
    }

    @Test
    public void testWithObjectPropertyEmptyString() {
        ObjectNode root = mapper.createObjectNode();
        ObjectNode child = root.withObjectProperty("");
        assertNotNull(child);
        assertTrue(child.isObject());
        assertSame(child, root.get(""));
    }

    @Test
    public void testWithArrayPropertyEmptyString() {
        ObjectNode root = mapper.createObjectNode();
        ArrayNode child = root.withArrayProperty("");
        assertNotNull(child);
        assertTrue(child.isArray());
        assertSame(child, root.get(""));
    }
}

