package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

public class JsonNodeWithPropertyTest {
    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testWithObjectProperty() {
        ObjectNode root = MAPPER.createObjectNode();

        // 1. Property does not exist -> should create new ObjectNode
        ObjectNode objNode = root.withObjectProperty("newObj");
        assertNotNull(objNode);
        assertTrue(root.has("newObj"));
        assertSame(objNode, root.get("newObj"));

        // 2. Property exists and is null -> should create new ObjectNode
        root.putNull("nullProp");
        ObjectNode objNode2 = root.withObjectProperty("nullProp");
        assertNotNull(objNode2);
        assertTrue(root.get("nullProp").isObject());
        assertSame(objNode2, root.get("nullProp"));

        // 3. Property exists and is an object -> should return existing ObjectNode
        ObjectNode existing = MAPPER.createObjectNode();
        existing.put("inner", "value");
        root.set("existingObj", existing);
        ObjectNode retrieved = root.withObjectProperty("existingObj");
        assertSame(existing, retrieved);
        assertEquals("value", retrieved.get("inner").asText());

        // 4. Property exists but is not an object and not null -> should throw UnsupportedOperationException
        root.put("stringProp", "text");
        try {
            root.withObjectProperty("stringProp");
            fail("Should have thrown an exception");
        } catch (UnsupportedOperationException e) {
            // Expected: Cannot replace JsonNode of type TextNode with ObjectNode
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("TextNode"));
            assertTrue(e.getMessage().contains("stringProp"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }

        // 5. Call on non-ObjectNode (e.g., ArrayNode) -> should throw UnsupportedOperationException
        ArrayNode arrayNode = MAPPER.createArrayNode();
        try {
            arrayNode.withObjectProperty("prop");
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // Expected
            assertTrue(e.getMessage().contains("cannot call `withObjectProperty(String)`"));
            assertTrue(e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithArrayProperty() {
        ObjectNode root = MAPPER.createObjectNode();

        // 1. Property does not exist -> should create new ArrayNode
        ArrayNode arrNode = root.withArrayProperty("newArr");
        assertNotNull(arrNode);
        assertTrue(root.has("newArr"));
        assertSame(arrNode, root.get("newArr"));

        // 2. Property exists and is null -> should create new ArrayNode
        root.putNull("nullArr");
        ArrayNode arrNode2 = root.withArrayProperty("nullArr");
        assertNotNull(arrNode2);
        assertTrue(root.get("nullArr").isArray());
        assertSame(arrNode2, root.get("nullArr"));

        // 3. Property exists and is an array -> should return existing ArrayNode
        ArrayNode existing = MAPPER.createArrayNode();
        existing.add(42);
        root.set("existingArr", existing);
        ArrayNode retrieved = root.withArrayProperty("existingArr");
        assertSame(existing, retrieved);
        assertEquals(42, retrieved.get(0).asInt());

        // 4. Property exists but is not an array and not null -> should throw UnsupportedOperationException
        root.put("intProp", 123);
        try {
            root.withArrayProperty("intProp");
            fail("Should have thrown an exception");
        } catch (UnsupportedOperationException e) {
            // Expected: Cannot replace JsonNode of type IntNode with ArrayNode
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("IntNode"));
            assertTrue(e.getMessage().contains("intProp"));
            assertTrue(e.getMessage().contains("OverwriteMode.NULLS"));
        }

        // 5. Call on non-ObjectNode (e.g., ArrayNode) -> should throw UnsupportedOperationException
        ArrayNode arrayNode = MAPPER.createArrayNode();
        try {
            arrayNode.withArrayProperty("prop");
            fail("Should have thrown UnsupportedOperationException");
