package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeParserTest {

    @Test
    public void testParseTypeWithExcessiveLength() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        StringBuilder sb = new StringBuilder();
        // Build a string longer than MAX_TYPE_LENGTH (64_000)
        for (int i = 0; i < 65000; i++) {
            sb.append('L');
        }
        String longType = sb.toString();
        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for too long type string");
        } catch (IllegalArgumentException e) {
            String message = e.getMessage();
            assertTrue("Message should contain 'too long'", message.contains("too long"));
            assertTrue("Message should contain 'maximum length allowed'", 
                      message.contains("maximum length allowed"));
            assertTrue("Message should contain length info", 
                      message.contains("65000"));
            assertTrue("Message should contain max length", 
                      message.contains("64000"));
            // Verify truncation for long input
            assertTrue("Message should be truncated", 
                      message.contains("...[truncated") || message.contains("...'[truncated"));
        }
    }

    @Test
    public void testParseTypeWithExcessiveNesting() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a deeply nested generic type that exceeds MAX_TYPE_NESTING (1000)
        // Using List<T> which has 1 type parameter
        StringBuilder sb = new StringBuilder("java.util.List");
        for (int i = 0; i < 1001; i++) {
            sb.append("<java.lang.String");
        }
        for (int i = 0; i < 1001; i++) {
            sb.append(">");
        }
        String deeplyNested = sb.toString();
        try {
            parser.parse(deeplyNested);
            fail("Expected IllegalArgumentException for too deeply nested type");
        } catch (IllegalArgumentException e) {
            String message = e.getMessage();
            assertTrue("Message should contain 'too deeply nested'", 
                      message.contains("too deeply nested"));
            assertTrue("Message should contain 'exceeds maximum'", 
                      message.contains("exceeds maximum"));
            assertTrue("Message should contain nesting limit", 
                      message.contains("1000"));
        }
    }

    @Test
    public void testParseTypeWithinLimits() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // A normal type string within limits should parse successfully
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.lang.Integer>");
        assertNotNull(type);
        assertEquals("java.util.Map", type.getRawClass().getName());
        assertEquals(2, type.containedTypeCount());
        assertEquals(String.class, type.containedType(0).getRawClass());
        assertEquals(Integer.class, type.containedType(1).getRawClass());
    }

    @Test
    public void testParseTypeWithDeepButValidNesting() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a deeply nested but still valid type (999 levels, just under the limit)
        // Using List<T> which has 1 type parameter
        StringBuilder sb = new StringBuilder("java.lang.String");
        for (int i = 0; i < 999; i++) {
            sb.append(">"); // Close all brackets
        }
        // Actually, we need to build it properly: List<List<List<...<String>...>>>
        // Let's create a simpler valid nested structure
        sb = new StringBuilder("java.util.List<java.lang.String>");
        for (int i = 1; i < 999; i++) {
            sb.insert(0, "java.util.List<");
            sb.append(">");
        }
        String deeplyNested = sb.toString();
        // This should parse successfully since it's within the limit
        JavaType type = parser.parse(deeplyNested);
        assertNotNull(type);
        // Verify it's a List type
        assertEquals("java.util.List", type.getRawClass().getName());
    }

    @Test
    public void testParseTypeWithLongButValidLength() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a long but valid type string (63,999 characters, just under the limit)
        // Use a valid class name with package that's long
        StringBuilder sb = new StringBuilder("java.util.Map<java.lang.String, ");
        // Add a long but valid type parameter
        sb.append("com.example.");
        int remaining = 63999 - sb.length() - 1; // -1 for closing '>'
        for (int i = 0; i < remaining; i++) {
            sb.append('C'); // Part of a valid class name
        }
        sb.append('>');
        String longType = sb.toString();

        // This will fail because "com.example.CCC..." is not a valid class
        // Instead, let's test with a valid type that's just under the limit
        // by using a simpler approach
        sb = new StringBuilder("java.util.List<java.lang.String>");
        while (sb.length() < 63999) {
            sb.insert(0, "java.util.List<");
            sb.append(">");
        }
        // Trim to exactly 63999
        if (sb.length() > 63999) {
            sb.setLength(63999);
        }
        longType = sb.toString();

        try {
            JavaType type = parser.parse(longType);
            assertNotNull(type);
            // It might fail due to nesting depth before hitting length limit
        } catch (IllegalArgumentException e) {
            // Acceptable if it fails due to nesting depth
            assertTrue(e.getMessage().contains("too deeply nested") || 
                      e.getMessage().contains("Cannot locate class"));
        }
    }

    @Test
    public void testErrorMessagesAreTruncatedForLongInputs() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Create a type string that's too long and also contains nesting
        StringBuilder sb = new StringBuilder("java.util.Map<");
        // Make it longer than MAX_TYPE_LENGTH
        for (int i = 0; i < 65000; i++) {
            sb.append('L');
        }
        sb.append('>');
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            String message = e.getMessage();
            // The error message should be truncated since input is very long
            assertTrue("Message should be truncated for long input",
                      message.contains("...[truncated") || message.contains("...'[truncated"));
            // Check for the typo in the error message (the patch has "charaters" instead of "characters")
            // This test documents the issue
            assertTrue("Message should contain truncation info",
                      message.contains("truncated") && message.contains("char"));
        }
    }

    @Test
    public void testNestedGenericTypesWithinLimit() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Test a complex but valid nested type
        String typeStr = "java.util.Map<java.lang.String, java.util.List<java.util.Map<java.lang.Integer, java.lang.String>>>";
        JavaType type = parser.parse(typeStr);
        assertNotNull(type);
        assertEquals("java.util.Map", type.getRawClass().getName());
        assertEquals(2, type.containedTypeCount());

        // Check the nested structure
        JavaType valueType = type.containedType(1);
        assertEquals("java.util.List", valueType.getRawClass().getName());
        assertEquals(1, valueType.containedTypeCount());

        JavaType mapType = valueType.containedType(0);
        assertEquals("java.util.Map", mapType.getRawClass().getName());
        assertEquals(2, mapType.containedTypeCount());
        assertEquals(Integer.class, mapType.containedType(0).getRawClass());
        assertEquals(String.class, mapType.containedType(1).getRawClass());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEmptyTypeString() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        parser.parse("");
    }

    @Test
    public void testMalformedTypeMissingClosingBracket() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        try {
            parser.parse("java.util.Map<java.lang.String, java.lang.Integer");
            fail("Expected IllegalArgumentException for malformed type");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Unexpected tokens") || 
                      e.getMessage().contains("Failed to parse"));
