package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.math.BigDecimal;

import static org.junit.Assert.*;

public class NumberDeserializersCoercionTest {

    // Test classes for different numeric types
    static class FloatWrapperBean {
        public Float value;
        public void setValue(Float v) { value = v; }
        public Float getValue() { return value; }
    }

    static class FloatPrimitiveBean {
        public float value;
        public void setValue(float v) { value = v; }
        public float getValue() { return value; }
    }

    static class DoubleWrapperBean {
        public Double value;
        public void setValue(Double v) { value = v; }
        public Double getValue() { return value; }
    }

    static class DoublePrimitiveBean {
        public double value;
        public void setValue(double v) { value = v; }
        public double getValue() { return value; }
    }

    static class BigDecimalBean {
        public BigDecimal value;
        public void setValue(BigDecimal v) { value = v; }
        public BigDecimal getValue() { return value; }
    }

    @Test
    public void testIntToFloatCoercionFail() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test Float wrapper
        try {
            mapper.readValue("{\"value\":42}", FloatWrapperBean.class);
            fail("Expected MismatchedInputException for FloatWrapperBean");
        } catch (MismatchedInputException e) {
            // expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test float primitive
        try {
            mapper.readValue("{\"value\":42}", FloatPrimitiveBean.class);
            fail("Expected MismatchedInputException for FloatPrimitiveBean");
        } catch (MismatchedInputException e) {
            // expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test Double wrapper
        try {
            mapper.readValue("{\"value\":42}", DoubleWrapperBean.class);
            fail("Expected MismatchedInputException for DoubleWrapperBean");
        } catch (MismatchedInputException e) {
            // expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test double primitive
        try {
            mapper.readValue("{\"value\":42}", DoublePrimitiveBean.class);
            fail("Expected MismatchedInputException for DoublePrimitiveBean");
        } catch (MismatchedInputException e) {
            // expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test BigDecimal
        try {
            mapper.readValue("{\"value\":42}", BigDecimalBean.class);
            fail("Expected MismatchedInputException for BigDecimalBean");
        } catch (MismatchedInputException e) {
            // expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }
    }

    @Test
    public void testIntToFloatCoercionAsNull() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Float wrapper: should be null
        FloatWrapperBean fwb = mapper.readValue("{\"value\":42}", FloatWrapperBean.class);
        assertNull(fwb.value);

        // Float primitive: should be 0.0f
        FloatPrimitiveBean fpb = mapper.readValue("{\"value\":42}", FloatPrimitiveBean.class);
        assertEquals(0.0f, fpb.value, 0.0f);

        // Double wrapper: should be null
        DoubleWrapperBean dwb = mapper.readValue("{\"value\":42}", DoubleWrapperBean.class);
        assertNull(dwb.value);

        // Double primitive: should be 0.0
        DoublePrimitiveBean dpb = mapper.readValue("{\"value\":42}", DoublePrimitiveBean.class);
        assertEquals(0.0, dpb.value, 0.0);

        // BigDecimal: should be null
        BigDecimalBean bdb = mapper.readValue("{\"value\":42}", BigDecimalBean.class);
        assertNull(bdb.value);
    }

    @Test
    public void testIntToFloatCoercionAsEmpty() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Float wrapper: getEmptyValue() returns 0.0f for wrapper types
        FloatWrapperBean fwb = mapper.readValue("{\"value\":42}", FloatWrapperBean.class);
        assertEquals(Float.valueOf(0.0f), fwb.value);

        // Float primitive: should be 0.0f
        FloatPrimitiveBean fpb = mapper.readValue("{\"value\":42}", FloatPrimitiveBean.class);
        assertEquals(0.0f, fpb.value, 0.0f);

        // Double wrapper: getEmptyValue() returns 0.0 for wrapper types
        DoubleWrapperBean dwb = mapper.readValue("{\"value\":42}", DoubleWrapperBean.class);
        assertEquals(Double.valueOf(0.0), dwb.value);

        // Double primitive: should be 0.0
        DoublePrimitiveBean dpb = mapper.readValue("{\"value\":42}", DoublePrimitiveBean.class);
        assertEquals(0.0, dpb.value, 0.0);

        // BigDecimal: getEmptyValue() returns BigDecimal.ZERO
        BigDecimalBean bdb = mapper.readValue("{\"value\":42}", BigDecimalBean.class);
        assertEquals(BigDecimal.ZERO, bdb.value);
    }

    @Test
    public void testIntToFloatCoercionTryConvert() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        // Default is TryConvert, but we set it explicitly to be safe
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.TryConvert);

        // All should convert integer to float/double/BigDecimal without issue
        FloatWrapperBean fwb = mapper.readValue("{\"value\":42}", FloatWrapperBean.class);
        assertEquals(Float.valueOf(42.0f), fwb.value);

        FloatPrimitiveBean fpb = mapper.readValue("{\"value\":42}", FloatPrimitiveBean.class);
        assertEquals(42.0f, fpb.value, 0.0f);

        DoubleWrapperBean dwb = mapper.readValue("{\"value\":42}", DoubleWrapperBean.class);
        assertEquals(Double.valueOf(42.0), dwb.value);

        DoublePrimitiveBean dpb = mapper.readValue("{\"value\":42}", DoublePrimitiveBean.class);
        assertEquals(42.0, dpb.value, 0.0);

        BigDecimalBean bdb = mapper.readValue("{\"value\":42}", BigDecimalBean.class);
        assertEquals(BigDecimal.valueOf(42), bdb.value);
    }

