        FloatWrapperBean fwb1 = mapper.readValue("{\"value\":0}", FloatWrapperBean.class);
        FloatWrapperBean fwb2 = mapper.readValue("{\"value\":123}", FloatWrapperBean.class);
        FloatWrapperBean fwb3 = mapper.readValue("{\"value\":-456}", FloatWrapperBean.class);

        assertEquals(fwb1.value, fwb2.value);
        assertEquals(fwb1.value, fwb3.value);
        assertEquals(Float.valueOf(0.0f), fwb1.value);
    }

