        assertEquals(Float.valueOf(42.5f), fwb.value);

        DoubleWrapperBean dwb = mapper.readValue("{\"value\":42.5}", DoubleWrapperBean.class);
        assertEquals(Double.valueOf(42.5), dwb.value);

        BigDecimalBean bdb = mapper.readValue("{\"value\":42.5}", BigDecimalBean.class);
        assertEquals(new BigDecimal("42.5"), bdb.value);
    }

    // New test: verify that coercion configuration doesn't affect non-integer tokens
    @Test
    public void testNonIntegerTokensUnaffected() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // String tokens should still work (with default coercion)
        FloatWrapperBean fwb = mapper.readValue("{\"value\":\"42.5\"}", FloatWrapperBean.class);
        assertEquals(Float.valueOf(42.5f), fwb.value);

        // Null tokens should work
        FloatWrapperBean fwbNull = mapper.readValue("{\"value\":null}", FloatWrapperBean.class);
        assertNull(fwbNull.value);

        // Boolean tokens should fail appropriately (not float type)
        try {
            mapper.readValue("{\"value\":true}", FloatWrapperBean.class);
            fail("Expected exception for boolean token");
        } catch (MismatchedInputException e) {
            // expected
        }
    }

    // New test: verify edge cases for integer values
    @Test
    public void testIntToFloatCoercionEdgeCases() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Test with zero
        FloatWrapperBean fwbZero = mapper.readValue("{\"value\":0}", FloatWrapperBean.class);
        assertNull(fwbZero.value);

        // Test with negative integer
        FloatWrapperBean fwbNeg = mapper.readValue("{\"value\":-123}", FloatWrapperBean.class);
        assertNull(fwbNeg.value);

        // Test with large integer that might overflow float
        FloatWrapperBean fwbLarge = mapper.readValue("{\"value\":999999999}", FloatWrapperBean.class);
        assertNull(fwbLarge.value);

        // Test with maximum integer value
        FloatWrapperBean fwbMax = mapper.readValue("{\"value\":2147483647}", FloatWrapperBean.class);
        assertNull(fwbMax.value);
    }

    // New test: verify that default behavior (no explicit config) still works
    @Test
    public void testDefaultCoercionBehavior() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        // No explicit configuration - should use default TryConvert

        // Integer should convert to float
        FloatWrapperBean fwb = mapper.readValue("{\"value\":42}", FloatWrapperBean.class);
        assertEquals(Float.valueOf(42.0f), fwb.value);

        // Float should work normally
        FloatWrapperBean fwbFloat = mapper.readValue("{\"value\":42.5}", FloatWrapperBean.class);
        assertEquals(Float.valueOf(42.5f), fwbFloat.value);

        // Test with different numeric types
        DoubleWrapperBean dwb = mapper.readValue("{\"value\":42}", DoubleWrapperBean.class);
        assertEquals(Double.valueOf(42.0), dwb.value);

        BigDecimalBean bdb = mapper.readValue("{\"value\":42}", BigDecimalBean.class);
        assertEquals(BigDecimal.valueOf(42), bdb.value);
    }

    // New test: verify mixed coercion configurations
    @Test
