package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeParserTest {

    @Test
    public void testParseTypeWithExcessiveLength() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        StringBuilder sb = new StringBuilder();
        // Build a string longer than MAX_TYPE_LENGTH (64,000)
        for (int i = 0; i < 65000; i++) {
            sb.append('L');
        }
        String longType = sb.toString();
        try {
            parser.parse(longType);
            fail("Should have thrown IllegalArgumentException for too long type");
        } catch (IllegalArgumentException e) {
            assertTrue("Message should contain 'too long': " + e.getMessage(),
                    e.getMessage().contains("too long"));
            assertTrue("Message should contain 'maximum length allowed': " + e.getMessage(),
                    e.getMessage().contains("maximum length allowed"));
            assertTrue("Message should contain '64000': " + e.getMessage(),
                    e.getMessage().contains("64000"));
            // Verify truncation in error message for long input
            assertTrue("Message should contain truncation indicator: " + e.getMessage(),
                    e.getMessage().contains("...'[truncated"));
        }
    }

    @Test
    public void testParseTypeWithExcessiveNesting() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a deeply nested generic type that exceeds MAX_TYPE_NESTING (1000)
        // Use valid class names to ensure we trigger nesting error, not class not found
        StringBuilder sb = new StringBuilder("java.lang.Object");
        for (int i = 0; i < 1001; i++) {
            sb.insert(0, "java.util.List<");
            sb.append(">");
        }
        String deeplyNested = sb.toString();
        try {
            parser.parse(deeplyNested);
            fail("Should have thrown IllegalArgumentException for too deep nesting");
        } catch (IllegalArgumentException e) {
            assertTrue("Message should contain 'too deeply nested': " + e.getMessage(),
                    e.getMessage().contains("too deeply nested"));
            assertTrue("Message should contain 'exceeds maximum': " + e.getMessage(),
                    e.getMessage().contains("exceeds maximum"));
            assertTrue("Message should contain '1000': " + e.getMessage(),
                    e.getMessage().contains("1000"));
        }
    }

    @Test
    public void testParseTypeWithValidLengthAndNesting() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a valid nested type within limits
        // Create: List<List<...<String>...>> with 100 levels
        StringBuilder sb = new StringBuilder("java.lang.String");
        for (int i = 0; i < 100; i++) {
            sb.insert(0, "java.util.List<");
            sb.append(">");
        }
        String validNested = sb.toString();
        // Should parse without exception
        JavaType type = parser.parse(validNested);
        assertNotNull(type);
        // Verify it's a List type
        assertEquals("java.util.List", type.getRawClass().getName());
    }

    @Test
    public void testParseTypeWithValidLength() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Build a type string that's exactly at the length limit
        // Use a simple type to avoid nesting issues
        StringBuilder sb = new StringBuilder();
        // Build a long class name by repeating a pattern
        sb.append("com.example.");
        for (int i = 0; i < 63980; i++) {
            sb.append('A');
        }
        String longButValid = sb.toString();

        // Ensure we're within limit
        assertTrue(longButValid.length() <= 64000);

        try {
            // This will fail because the class doesn't exist, but should pass length check
            parser.parse(longButValid);
            // If we get here, the length check passed (though class resolution will fail)
            // We expect a different exception for class not found
        } catch (IllegalArgumentException e) {
            // Should not be a length error
            assertFalse("Should not be a length error: " + e.getMessage(),
                    e.getMessage().contains("too long"));
            assertFalse("Should not mention maximum length: " + e.getMessage(),
                    e.getMessage().contains("maximum length allowed"));
            // Should be a class not found error
            assertTrue("Should mention class resolution: " + e.getMessage(),
                    e.getMessage().contains("Failed to parse type"));
        }
    }

    @Test
    public void testQuoteTruncatedShort() {
        // Test the _quoteTruncated method behavior through public API
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        String shortType = "java.lang.String";
        try {
            parser.parse(shortType + "<"); // Malformed to trigger error
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            // The short type should be fully quoted
            assertTrue("Should contain quoted type: " + msg,
                    msg.contains("'java.lang.String<'"));
        }
    }

    @Test
    public void testQuoteTruncatedLong() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Create a type that's too long to trigger the length check
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 65000; i++) {
            sb.append('L');
        }
        String longType = sb.toString();
        try {
            parser.parse(longType);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            // Should show truncation for the long input
            assertTrue("Should contain truncation indicator: " + msg,
                    msg.contains("...'[truncated"));
            // Note: There's a typo in the implementation - "charaters" instead of "characters"
            assertTrue("Should contain truncated length: " + msg,
                    msg.contains("[truncated"));
        }
    }

    @Test
    public void testProblemMessageIncludesTruncatedInput() {
        TypeParser parser = new TypeParser(TypeFactory.defaultInstance());
        // Create a type that's too long to trigger the length check
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 65000; i++) {
            sb.append('L');
        }
        String longType = sb.toString();
        try {
            parser.parse(longType);
