    public void testIntCoercionAsEmptyForAllTypes() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Test all wrapper types return appropriate empty values for AsEmpty
        FloatWrapper fw = mapper.readValue("{\"value\": 123}", FloatWrapper.class);
        assertEquals("Float wrapper should return Float.valueOf(0.0f) for AsEmpty", 
                     Float.valueOf(0.0f), fw.value);

        DoubleWrapper dw = mapper.readValue("{\"value\": 456}", DoubleWrapper.class);
        assertEquals("Double wrapper should return Double.valueOf(0.0d) for AsEmpty", 
                     Double.valueOf(0.0d), dw.value);

        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 789}", BigDecimalWrapper.class);
        assertEquals("BigDecimal wrapper should return BigDecimal.ZERO for AsEmpty", 
                     BigDecimal.ZERO, bdw.value);

        // Test all primitive types return 0 for AsEmpty
        PrimitiveFloatWrapper pf = mapper.readValue("{\"value\": 123}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pf.value, 0.0f);

        PrimitiveDoubleWrapper pd = mapper.readValue("{\"value\": 456}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0d, pd.value, 0.0d);
    }

