    // Test to cover edge case with very large integer that fits in BigDecimal
    @Test
    public void testVeryLargeIntegerCoercion() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // Test with default coercion (should succeed)
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 999999999999999999999999999}", BigDecimalWrapper.class);
        assertEquals(new BigDecimal("999999999999999999999999999"), bdw.value);

        // Test with Fail action (should throw)
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 999999999999999999999999999}", BigDecimalWrapper.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

